#include "dual_state_cpu.hpp"
#include <cstdio>
int main(){try{tao::dual::Config c;c.layers=2;c.d=4;c.s=2;c.m=3;c.e=8;c.vocab=261;tao::dual::CpuModel m(c);for(auto&kv:m.w)for(size_t j=0;j<kv.second.size();++j)kv.second[j]=kv.first.find("norm")!=std::string::npos?1.f:float(int(j%7)-3)*.01f;auto a=m.initial(),b=m.initial();for(unsigned token:{256u,257u,65u,259u,258u,66u}){auto x=m.step(token,a),y=m.step(token,b);if(x!=y)throw std::runtime_error("replay");for(float z:x)if(!std::isfinite(z))throw std::runtime_error("finite");for(auto&l:a){for(float z:l.s)if(std::abs(z)>1)throw std::runtime_error("s bound");for(float z:l.m)if(std::abs(z)>1)throw std::runtime_error("m bound");}}bool rejected=false;try{m.step(261,a);}catch(const std::invalid_argument&){rejected=true;}if(!rejected)throw std::runtime_error("token");printf("PASS small-shape causal replay finite states and invalid token; not independent reference parity\n");return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
